INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c565474e-80fc-59f0-9b53-7f5ee1a94150', 'Isle of Man Environmental Protection Bill Consultation', 'Environmental Protection Bill Consultation', 'The Environmental Protection Bill Consultation in Isle of Man aims to establish regulations for environmental protection, emphasizing offshore energy development, water pollution control, and pollution response. Seeking feedback from stakeholders, it targets ensuring compliance with international standards and protecting the environment for future generations.', 'The Environmental Protection Bill Consultation in Isle of Man aims to establish regulations for environmental protection, emphasizing offshore energy development, water pollution control, and pollution response. Seeking feedback from stakeholders, it targets ensuring compliance with international standards and protecting the environment for future generations.', 'The Environmental Protection Bill Consultation in Isle of Man aims to establish regulations for environmental protection, emphasizing offshore energy development, water pollution control, and pollution response. Seeking feedback from stakeholders, it targets ensuring compliance with international standards and protecting the environment for future generations.', 'Isle of Man', 'climate', 'in_force', '2025-01-01'::date, 'Isle of Man', 'https://www.carrotsandsticks.org/policies/83_2', ARRAY['regulations', 'sdg7', 'mandatory', 'sdg6', 'isle of man']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9c5fd2b6-f1c1-5897-815a-b0d842b62671', 'Isle of Man Managing the Financial Risks of Climate', 'Managing the Financial Risks of Climate Change and Nature Loss', 'The policy document from Isle of Man, issued in 2025, focuses on managing financial risks from climate change and nature loss for regulated firms under specific acts. It outlines definitions, governance, risk management, scenario analysis, and disclosure requirements to assist compliance and best practices. Target audience: Firms regulated by financial acts.', 'The policy document from Isle of Man, issued in 2025, focuses on managing financial risks from climate change and nature loss for regulated firms under specific acts. It outlines definitions, governance, risk management, scenario analysis, and disclosure requirements to assist compliance and best practices. Target audience: Firms regulated by financial acts.', 'The policy document from Isle of Man, issued in 2025, focuses on managing financial risks from climate change and nature loss for regulated firms under specific acts. It outlines definitions, governance, risk management, scenario analysis, and disclosure requirements to assist compliance and best practices. Target audience: Firms regulated by financial acts.', 'Isle of Man', 'climate', 'in_force', '2025-01-01'::date, 'Isle of Man', 'https://www.carrotsandsticks.org/policies/83_4', ARRAY['sdg13', 'regulations', 'mandatory', 'sdg16', 'sdg15', 'isle of man']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8f32ec29-6feb-5f54-9197-267638795264', 'Isle of Man Greenwashing and Consumer Protection', 'Greenwashing and Consumer Protection', 'The Greenwashing and Consumer Protection policy by the Isle of Man Financial Services Authority aims to guide regulated firms on accurate and transparent environmental claims, focusing on substantiation, clarity, completeness, fairness in comparisons, and alignment with corporate strategy. It targets firms under specific financial acts to prevent misleading consumers and ensure compliance.', 'The Greenwashing and Consumer Protection policy by the Isle of Man Financial Services Authority aims to guide regulated firms on accurate and transparent environmental claims, focusing on substantiation, clarity, completeness, fairness in comparisons, and alignment with corporate strategy. It targets firms under specific financial acts to prevent misleading consumers and ensure compliance.', 'The Greenwashing and Consumer Protection policy by the Isle of Man Financial Services Authority aims to guide regulated firms on accurate and transparent environmental claims, focusing on substantiation, clarity, completeness, fairness in comparisons, and alignment with corporate strategy. It targets firms under specific financial acts to prevent misleading consumers and ensure compliance.', 'Isle of Man', 'governance', 'in_force', '2025-01-01'::date, 'Isle of Man', 'https://www.carrotsandsticks.org/policies/83_5', ARRAY['isle of man', 'mandatory', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('65be6ca0-8e1b-56df-ac3d-5f01efb831c3', 'Isle of Man Climate Change Act', 'Climate Change Act 2021', 'The Climate Change Act 2021 in Isle of Man establishes a net zero emissions target by 2050 and sets interim targets for greenhouse gas reduction. It mandates climate change duties for public bodies, regulates fossil fuels and single-use plastics, and requires planning and reporting on emissions. Target audience: policymakers, public bodies, and environmental stakeholders.', 'The Climate Change Act 2021 in Isle of Man establishes a net zero emissions target by 2050 and sets interim targets for greenhouse gas reduction. It mandates climate change duties for public bodies, regulates fossil fuels and single-use plastics, and requires planning and reporting on emissions. Target audience: policymakers, public bodies, and environmental stakeholders.', 'The Climate Change Act 2021 in Isle of Man establishes a net zero emissions target by 2050 and sets interim targets for greenhouse gas reduction. It mandates climate change duties for public bodies, regulates fossil fuels and single-use plastics, and requires planning and reporting on emissions. Target audience: policymakers, public bodies, and environmental stakeholders.', 'Isle of Man', 'climate', 'in_force', '2021-01-01'::date, 'Isle of Man', 'https://www.carrotsandsticks.org/policies/83_3', ARRAY['sdg13', 'regulations', 'sdg7', 'mandatory', 'isle of man']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d2b6a0a0-78f6-5e8b-8e6d-10d893c8305a', 'Israel Amendment to the provisions of the Consolidated Circular', 'Amendment to the provisions of the Consolidated Circular - Chapter 4 of Title 5', 'Stipulates the framework for overall investment policy determined by the Investment Committee of an institutional investor, by which an investment policy will be determined in relation to ESG considerations that are relevant to an investment portfolio.', 'Stipulates the framework for overall investment policy determined by the Investment Committee of an institutional investor, by which an investment policy will be determined in relation to ESG considerations that are relevant to an investment portfolio.', 'Stipulates the framework for overall investment policy determined by the Investment Committee of an institutional investor, by which an investment policy will be determined in relation to ESG considerations that are relevant to an investment portfolio.', 'Israel', 'climate', 'in_force', '2021-01-01'::date, 'Israel', 'https://www.carrotsandsticks.org/policies/84_9', ARRAY['sdg13', 'other sustainability policy', 'mandatory', 'israel', 'sdg16', 'mandatory_regulations', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('144f4c7d-997a-5c6a-a3df-a11952d65084', 'Israel Sustainable Consumption and Production Roadmap', 'Sustainable Consumption and Production Roadmap', 'In order to promote sustainable production, the MoEP and the Ministry of Economy have developed or are in the process of developing a number of projects, as detailed in the action plan.', 'In order to promote sustainable production, the MoEP and the Ministry of Economy have developed or are in the process of developing a number of projects, as detailed in the action plan.', 'In order to promote sustainable production, the MoEP and the Ministry of Economy have developed or are in the process of developing a number of projects, as detailed in the action plan.', 'Israel', 'circularity', 'in_force', '2015-01-01'::date, 'Israel', 'https://www.carrotsandsticks.org/policies/84_8', ARRAY['other sustainability policy', 'mandatory', 'israel', 'mandatory_regulations', 'sdg12', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f9b56caa-61bc-58f1-83c7-3feb5df399ba', 'Israel Environmental Protection Law (Supervisory and Enforcement Powers)', 'Environmental Protection Law (Supervisory and Enforcement Powers), 2011', 'The purpose of this law is to protect and maintain the proper quality of the environment and to improve and prevent harm to the environment or public health, by anchoring and expanding the supervisory and enforcement powers of employees of the Ministry of Environmental Protection.', 'The purpose of this law is to protect and maintain the proper quality of the environment and to improve and prevent harm to the environment or public health, by anchoring and expanding the supervisory and enforcement powers of employees of the Ministry of Environmental Protection.', 'The purpose of this law is to protect and maintain the proper quality of the environment and to improve and prevent harm to the environment or public health, by anchoring and expanding the supervisory and enforcement powers of employees of the Ministry of Environmental Protection.', 'Israel', 'climate', 'in_force', '2011-01-01'::date, 'Israel', 'https://www.carrotsandsticks.org/policies/84_2', ARRAY['sdg14', 'other sustainability policy', 'regulations', 'mandatory', 'israel', 'sdg12', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('46569b9a-7868-5b1d-8c87-b8f914764274', 'Israel Public Reporting Directives [11] (): Annual Report', 'Public Reporting Directives [11] (6/09): Annual Report of a Banking Corporation', 'The board of directors of a banking corporation will submit to the annual general meeting of shareholders the annual financial report approved by it, which will include a report and explanations regarding the events and changes that have occurred in the statement of affairs of the banking corporation and that have affected the statements, in accordance with the details mentioned in these provisions (hereinafter: “the report of the board of directors”).', 'The board of directors of a banking corporation will submit to the annual general meeting of shareholders the annual financial report approved by it, which will include a report and explanations regarding the events and changes that have occurred in the statement of affairs of the banking corporation and that have affected the statements, in accordance with the details mentioned in these provisions (hereinafter: “the report of the board of directors”).', 'The board of directors of a banking corporation will submit to the annual general meeting of shareholders the annual financial report approved by it, which will include a report and explanations regarding the events and changes that have occurred in the statement of affairs of the banking corporation and that have affected the statements, in accordance with the details mentioned in these provisions (hereinafter: “the report of the board of directors”).', 'Israel', 'climate', 'in_force', '2011-01-01'::date, 'Israel', 'https://www.carrotsandsticks.org/policies/84_4', ARRAY['regulations', 'mandatory', 'israel', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4c5fa1e4-e87c-58d7-bd65-76836c747fe4', 'Israel Greenhouse Gas Registry', 'Greenhouse Gas Registry', 'This document presents an English language synopsis of the General Reporting Protocol and Reporting Guidelines document (the ‘Israel GHG Protocol’) that was prepared by a team from the Environment and Energy Cluster at the Samuel Neaman Institute (SNI) for national policy research at the Technion, Israel Institute of Technology. The work was conducted during 2009- 2010, as a joint project with the Israel Ministry of Environmental Protection. To aid with the process an expert working group was formed, representing all major sectors of the Israeli economy.', 'This document presents an English language synopsis of the General Reporting Protocol and Reporting Guidelines document (the ‘Israel GHG Protocol’) that was prepared by a team from the Environment and Energy Cluster at the Samuel Neaman Institute (SNI) for national policy research at the Technion, Israel Institute of Technology. The work was conducted during 2009- 2010, as a joint project with the Israel Ministry of Environmental Protection. To aid with the process an expert working group was formed, representing all major sectors of the Israeli economy.', 'This document presents an English language synopsis of the General Reporting Protocol and Reporting Guidelines document (the ‘Israel GHG Protocol’) that was prepared by a team from the Environment and Energy Cluster at the Samuel Neaman Institute (SNI) for national policy research at the Technion, Israel Institute of Technology. The work was conducted during 2009- 2010, as a joint project with the Israel Ministry of Environmental Protection. To aid with the process an expert working group was formed, representing all major sectors of the Israeli economy.', 'Israel', 'climate', 'in_force', '2011-01-01'::date, 'Israel', 'https://www.carrotsandsticks.org/policies/84_5', ARRAY['guidance_frameworks', 'sdg13', 'sdg14', 'other sustainability policy', 'sdg7', 'mandatory', 'israel']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b07c6186-2ace-5e25-8ae9-8ce057915019', 'Israel Goshen Report', 'The Goshen Report, 2006', 'The Goshen Committee recommendations focus on improvement of director independence, particularly regarding approval of related party transactions, improvement in the workings of auditing\balance committees, pertaining to approval of company''s financial statements, improvement of corporate disclosure and accountability and establishment of a Court for Securities and Corporate Offences.', 'The Goshen Committee recommendations focus on improvement of director independence, particularly regarding approval of related party transactions, improvement in the workings of auditing\balance committees, pertaining to approval of company''s financial statements, improvement of corporate disclosure and accountability and establishment of a Court for Securities and Corporate Offences.', 'The Goshen Committee recommendations focus on improvement of director independence, particularly regarding approval of related party transactions, improvement in the workings of auditing\balance committees, pertaining to approval of company''s financial statements, improvement of corporate disclosure and accountability and establishment of a Court for Securities and Corporate Offences.', 'Israel', 'climate', 'in_force', '2006-01-01'::date, 'Israel', 'https://www.carrotsandsticks.org/policies/84_11', ARRAY['other sustainability policy', 'sdg7', 'mandatory', 'israel', 'sdg16', 'mandatory_regulations', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6927a968-6058-5907-a32b-64584c74020d', 'Italy Legislative Decree 8 August 2025 n. 116', 'Legislative Decree 8 August 2025 n. 116', 'Legislative Decree 8 August 2025 n. 116 in Italy aims to combat illegal waste activities, clean up contaminated areas like Terra dei Fuochi, and provide assistance to populations affected by disasters. It introduces urgent measures to address these issues, with modifications to existing legislation, focusing on waste management and environmental protection. Targeted at businesses, individuals, and entities involved in waste transportation and disposal.', 'Legislative Decree 8 August 2025 n. 116 in Italy aims to combat illegal waste activities, clean up contaminated areas like Terra dei Fuochi, and provide assistance to populations affected by disasters. It introduces urgent measures to address these issues, with modifications to existing legislation, focusing on waste management and environmental protection. Targeted at businesses, individuals, and entities involved in waste transportation and disposal.', 'Legislative Decree 8 August 2025 n. 116 in Italy aims to combat illegal waste activities, clean up contaminated areas like Terra dei Fuochi, and provide assistance to populations affected by disasters. It introduces urgent measures to address these issues, with modifications to existing legislation, focusing on waste management and environmental protection. Targeted at businesses, individuals, and entities involved in waste transportation and disposal.', 'Italy', 'climate', 'in_force', '2025-01-01'::date, 'Italy', 'https://www.carrotsandsticks.org/policies/85_54', ARRAY['italy', 'regulations', 'sdg11', 'mandatory', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('84721ef3-a500-5708-a1fd-40d5b9da5a44', 'Italy Legislative Decree 8 August', 'Legislative Decree 8 August 2025 No. 118', 'Legislative Decree 8 August 2025 No. 118 aims to provide urgent provisions for the financing of economic activities and enterprises, as well as social interventions and matters related to infrastructure and transportation. It applies to various sectors involved in economic activities and social services. The decree includes mandatory requirements for compliance with the outlined provisions, ensuring that entities adhere to the new regulations for funding and operational guidelines.', 'Legislative Decree 8 August 2025 No. 118 aims to provide urgent provisions for the financing of economic activities and enterprises, as well as social interventions and matters related to infrastructure and transportation. It applies to various sectors involved in economic activities and social services. The decree includes mandatory requirements for compliance with the outlined provisions, ensuring that entities adhere to the new regulations for funding and operational guidelines.', 'Legislative Decree 8 August 2025 No. 118 aims to provide urgent provisions for the financing of economic activities and enterprises, as well as social interventions and matters related to infrastructure and transportation. It applies to various sectors involved in economic activities and social services. The decree includes mandatory requirements for compliance with the outlined provisions, ensuring that entities adhere to the new regulations for funding and operational guidelines.', 'Italy', 'climate', 'in_force', '2025-01-01'::date, 'Italy', 'https://www.carrotsandsticks.org/policies/85_55', ARRAY['italy', 'regulations', 'sdg11', 'mandatory', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d7fc4d25-a7f5-582a-9d38-34be1105af12', 'Italy Legislative Decree 6 September 2024 n. 125', 'Legislative Decree 6 September 2024 n. 125', 'This policy was published in 2024 by Italy. It addresses sustainability and corporate responsibility requirements.', 'This policy was published in 2024 by Italy. It addresses sustainability and corporate responsibility requirements.', 'This policy was published in 2024 by Italy. It addresses sustainability and corporate responsibility requirements.', 'Italy', 'climate', 'in_force', '2024-01-01'::date, 'Italy', 'https://www.carrotsandsticks.org/policies/85_53', ARRAY['sdg13', 'italy', 'regulations', 'mandatory', 'sdg16', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3610e65e-c58f-5e17-8d51-a69689db1a93', 'Italy Corporate Governance Code', 'Corporate Governance Code 2020', 'The Corporate Governance Code ("Code") applies to all companies with shares listed on the Italian main market (“Mercato Telematico Azionario”, hereinafter “MTA") managed by Borsa Italiana ("companies"). Adoption of this Code is voluntary and is disclosed in the report on corporate governance and ownership structures ("corporate governance report").', 'The Corporate Governance Code ("Code") applies to all companies with shares listed on the Italian main market (“Mercato Telematico Azionario”, hereinafter “MTA") managed by Borsa Italiana ("companies"). Adoption of this Code is voluntary and is disclosed in the report on corporate governance and ownership structures ("corporate governance report").', 'The Corporate Governance Code ("Code") applies to all companies with shares listed on the Italian main market (“Mercato Telematico Azionario”, hereinafter “MTA") managed by Borsa Italiana ("companies"). Adoption of this Code is voluntary and is disclosed in the report on corporate governance and ownership structures ("corporate governance report").', 'Italy', 'climate', 'in_force', '2020-01-01'::date, 'Italy', 'https://www.carrotsandsticks.org/policies/85_52', ARRAY['other sustainability policy', 'italy', 'mandatory', 'sdg16', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('cf14e095-b92e-541c-8673-316810640eac', 'Italy Corporate Governance Code', 'Corporate Governance Code 2018', 'The Italian Corporate Governance Code 2018 sets voluntary guidelines for listed companies to enhance transparency and accountability in corporate governance. It outlines principles, criteria, and comments for effective board functioning, risk management, and performance evaluation. Companies are required to provide detailed information on Code implementation in their corporate governance reports. The Code allows flexibility but mandates explanations for non-compliance. The Corporate Governance Committee monitors Code implementation and updates it regularly to align with best practices.', 'The Italian Corporate Governance Code 2018 sets voluntary guidelines for listed companies to enhance transparency and accountability in corporate governance. It outlines principles, criteria, and comments for effective board functioning, risk management, and performance evaluation. Companies are required to provide detailed information on Code implementation in their corporate governance reports. The Code allows flexibility but mandates explanations for non-compliance. The Corporate Governance Committee monitors Code implementation and updates it regularly to align with best practices.', 'The Italian Corporate Governance Code 2018 sets voluntary guidelines for listed companies to enhance transparency and accountability in corporate governance. It outlines principles, criteria, and comments for effective board functioning, risk management, and performance evaluation. Companies are required to provide detailed information on Code implementation in their corporate governance reports. The Code allows flexibility but mandates explanations for non-compliance. The Corporate Governance Committee monitors Code implementation and updates it regularly to align with best practices.', 'Italy', 'climate', 'in_force', '2018-01-01'::date, 'Italy', 'https://www.carrotsandsticks.org/policies/85_17', ARRAY['italy', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e1f3de01-1753-556a-9136-f82a806be85d', 'Italy Italian Corporate Governance Principles For Unlisted Familly-Controlled Companies', 'Italian Corporate Governance Principles For Unlisted Familly-Controlled Companies - 2017', 'This Code proposes some principles and guidelines that can be summed up in an "executive summary" for entrepreneurial families who, by controlling family companies larger than minimal size, may be willing to assess their compliance.', 'This Code proposes some principles and guidelines that can be summed up in an "executive summary" for entrepreneurial families who, by controlling family companies larger than minimal size, may be willing to assess their compliance.', 'This Code proposes some principles and guidelines that can be summed up in an "executive summary" for entrepreneurial families who, by controlling family companies larger than minimal size, may be willing to assess their compliance.', 'Italy', 'governance', 'in_force', '2017-01-01'::date, 'Italy', 'https://www.carrotsandsticks.org/policies/85_19', ARRAY['guidance_frameworks', 'other sustainability policy', 'italy', 'sdg16', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('41bbd5f7-ea13-5fc1-96de-027c1cdf04e0', 'Italy Legislative Decree', 'Legislative Decree 254/2016', 'On December 30, 2016, the Italian government approved Legislative Decree No. 254/2016 implementing EC Directive 2014/95/EU.', 'On December 30, 2016, the Italian government approved Legislative Decree No. 254/2016 implementing EC Directive 2014/95/EU.', 'On December 30, 2016, the Italian government approved Legislative Decree No. 254/2016 implementing EC Directive 2014/95/EU.', 'Italy', 'governance', 'in_force', '2017-01-01'::date, 'Italy', 'https://www.carrotsandsticks.org/policies/85_44', ARRAY['other sustainability policy', 'italy', 'regulations', 'mandatory', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ee708a58-aaa2-5aab-9897-3902729ae2cb', 'Italy Legislative Decree', 'Legislative Decree 2016', 'The President of the Republic has approved a legislative decree regarding the code of accounting justice, including implementing rules, transitional rules, and repeals. The decree will enter into force 30 days after it is published in the Official Gazette of the Italian Republic. The decree is binding and must be observed by all concerned.', 'The President of the Republic has approved a legislative decree regarding the code of accounting justice, including implementing rules, transitional rules, and repeals. The decree will enter into force 30 days after it is published in the Official Gazette of the Italian Republic. The decree is binding and must be observed by all concerned.', 'The President of the Republic has approved a legislative decree regarding the code of accounting justice, including implementing rules, transitional rules, and repeals. The decree will enter into force 30 days after it is published in the Official Gazette of the Italian Republic. The decree is binding and must be observed by all concerned.', 'Italy', 'governance', 'in_force', '2016-01-01'::date, 'Italy', 'https://www.carrotsandsticks.org/policies/85_11', ARRAY['other sustainability policy', 'italy', 'regulations', 'mandatory', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f9df7f5b-004e-5594-b1fb-176e2ec66667', 'Italy Italian Stewardship Principles for the exercise of administrative', 'Italian Stewardship Principles for the exercise of administrative and voting rights in listed companies 2016', 'The purpose of these Principles is to provide a set of high-level best practices designed to promote discussion and cooperation between Investment Management Companies and listed issuers in which assets are invested, as part of the collective management or portfolio management services they provide.', 'The purpose of these Principles is to provide a set of high-level best practices designed to promote discussion and cooperation between Investment Management Companies and listed issuers in which assets are invested, as part of the collective management or portfolio management services they provide.', 'The purpose of these Principles is to provide a set of high-level best practices designed to promote discussion and cooperation between Investment Management Companies and listed issuers in which assets are invested, as part of the collective management or portfolio management services they provide.', 'Italy', 'climate', 'in_force', '2016-01-01'::date, 'Italy', 'https://www.carrotsandsticks.org/policies/85_21', ARRAY['guidance_frameworks', 'other sustainability policy', 'italy', 'sdg17', 'sdg16', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('bf572ad7-b9c8-5a73-b6a8-f39942307bc9', 'Italy Corporate Governance Code', 'Corporate Governance Code 2015', 'The 2015 Italian Corporate Governance Code is a voluntary policy focusing on governance principles for listed companies. It outlines criteria for boards of directors to ensure effective decision-making, risk management, and sustainable business practices. Companies must disclose their compliance with the code in their corporate governance reports, including explanations for any departures from recommendations. The Corporate Governance Committee monitors code implementation and updates every two years. Amendments introduced in 2015 require companies to implement new remuneration policies and changes to the board of statutory auditors.', 'The 2015 Italian Corporate Governance Code is a voluntary policy focusing on governance principles for listed companies. It outlines criteria for boards of directors to ensure effective decision-making, risk management, and sustainable business practices. Companies must disclose their compliance with the code in their corporate governance reports, including explanations for any departures from recommendations. The Corporate Governance Committee monitors code implementation and updates every two years. Amendments introduced in 2015 require companies to implement new remuneration policies and changes to the board of statutory auditors.', 'The 2015 Italian Corporate Governance Code is a voluntary policy focusing on governance principles for listed companies. It outlines criteria for boards of directors to ensure effective decision-making, risk management, and sustainable business practices. Companies must disclose their compliance with the code in their corporate governance reports, including explanations for any departures from recommendations. The Corporate Governance Committee monitors code implementation and updates every two years. Amendments introduced in 2015 require companies to implement new remuneration policies and changes to the board of statutory auditors.', 'Italy', 'climate', 'in_force', '2015-01-01'::date, 'Italy', 'https://www.carrotsandsticks.org/policies/85_2', ARRAY['italy', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('57eff1c1-2149-5027-9831-c63c14d96385', 'Italy Italian Stewardship Principles for the exercise of administrative', 'Italian Stewardship Principles for the exercise of administrative and voting rights in listed companies 2015', 'These principles, accompanied by a series of best-practice Recommendations, are aimed at companies that provide collective investment management or portfolio management services, in order to promote discussion and cooperation between Investment Management Companies and listed issuers in which they invest.', 'These principles, accompanied by a series of best-practice Recommendations, are aimed at companies that provide collective investment management or portfolio management services, in order to promote discussion and cooperation between Investment Management Companies and listed issuers in which they invest.', 'These principles, accompanied by a series of best-practice Recommendations, are aimed at companies that provide collective investment management or portfolio management services, in order to promote discussion and cooperation between Investment Management Companies and listed issuers in which they invest.', 'Italy', 'climate', 'in_force', '2015-01-01'::date, 'Italy', 'https://www.carrotsandsticks.org/policies/85_20', ARRAY['guidance_frameworks', 'italy', 'sdg17', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d3ae6789-a934-5eb2-8e15-570a7c390a54', 'Italy Law 28 December 2015, n. 208. Provisions', 'Law 28 December 2015, n. 208. Provisions for the preparation of the annual and multiannual state budget (2016 stability law)', 'Law 28 December 2015, n. 208 in Italy sets provisions for the formation of the annual and multiannual state budget, focusing on financial aspects such as net balances, market financing, and transfer adjustments. The law also addresses pension obligations, expert accountants'' registrations, and tax adjustments. It aims to ensure financial stability and appropriate funding allocations for various government functions.', 'Law 28 December 2015, n. 208 in Italy sets provisions for the formation of the annual and multiannual state budget, focusing on financial aspects such as net balances, market financing, and transfer adjustments. The law also addresses pension obligations, expert accountants'' registrations, and tax adjustments. It aims to ensure financial stability and appropriate funding allocations for various government functions.', 'Law 28 December 2015, n. 208 in Italy sets provisions for the formation of the annual and multiannual state budget, focusing on financial aspects such as net balances, market financing, and transfer adjustments. The law also addresses pension obligations, expert accountants'' registrations, and tax adjustments. It aims to ensure financial stability and appropriate funding allocations for various government functions.', 'Italy', 'governance', 'in_force', '2015-01-01'::date, 'Italy', 'https://www.carrotsandsticks.org/policies/85_3', ARRAY['italy', 'mandatory', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
