INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c0373bbe-82b8-50ad-aeec-d30e17e3cbc2', 'Italy Corporate Governance Code', 'Corporate Governance Code 2014', 'The 2014 Italian Corporate Governance Code outlines voluntary adoption and compliance principles for listed companies, with recommendations for board roles, risk management, and disclosure practices. Issuers must provide detailed reports on implementing each recommendation, with explanations for any deviations. The Code allows flexibility in compliance but requires clear explanations for non-compliance. The Corporate Governance Committee monitors implementation and updates the Code periodically. Companies are encouraged to adopt specific amendments by set dates. The policy aims to enhance transparency, accountability, and governance practices in listed companies operating in Italy.', 'The 2014 Italian Corporate Governance Code outlines voluntary adoption and compliance principles for listed companies, with recommendations for board roles, risk management, and disclosure practices. Issuers must provide detailed reports on implementing each recommendation, with explanations for any deviations. The Code allows flexibility in compliance but requires clear explanations for non-compliance. The Corporate Governance Committee monitors implementation and updates the Code periodically. Companies are encouraged to adopt specific amendments by set dates. The policy aims to enhance transparency, accountability, and governance practices in listed companies operating in Italy.', 'The 2014 Italian Corporate Governance Code outlines voluntary adoption and compliance principles for listed companies, with recommendations for board roles, risk management, and disclosure practices. Issuers must provide detailed reports on implementing each recommendation, with explanations for any deviations. The Code allows flexibility in compliance but requires clear explanations for non-compliance. The Corporate Governance Committee monitors implementation and updates the Code periodically. Companies are encouraged to adopt specific amendments by set dates. The policy aims to enhance transparency, accountability, and governance practices in listed companies operating in Italy.', 'Italy', 'climate', 'in_force', '2014-01-01'::date, 'Italy', 'https://www.carrotsandsticks.org/policies/85_15', ARRAY['italy', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
