INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('106b7c02-3cc3-5ee9-a59d-d3fc5d7d7b84', 'Italy Social Report GBS 2013 Standard Principles of Drafting', 'The Social Report GBS 2013 Standard Principles of Drafting of the Social Report', 'The document presents and illustrates the principles and indications procedural considered essential for the preparation of the Financial Statements Social. These principles and indications were partly derived from experience and doctrine, and partly developed with the discussion and comparison with international accountability models.', 'The document presents and illustrates the principles and indications procedural considered essential for the preparation of the Financial Statements Social. These principles and indications were partly derived from experience and doctrine, and partly developed with the discussion and comparison with international accountability models.', 'The document presents and illustrates the principles and indications procedural considered essential for the preparation of the Financial Statements Social. These principles and indications were partly derived from experience and doctrine, and partly developed with the discussion and comparison with international accountability models.', 'Italy', 'climate', 'in_force', '2013-01-01'::date, 'Italy', 'https://www.carrotsandsticks.org/policies/85_10', ARRAY['sdg14', 'other sustainability policy', 'italy', 'voluntary', 'sdg16', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('63462cdd-53d9-5088-ae14-51581502802d', 'Italy Italian Stewardship Principles for the exercise of administrative', 'Italian Stewardship Principles for the exercise of administrative and voting rights in listed companies 2013', 'This is the 2013 version of the Italian Stewardship principles for the exercise of administrative and voting rights in listed companies.', 'This is the 2013 version of the Italian Stewardship principles for the exercise of administrative and voting rights in listed companies.', 'This is the 2013 version of the Italian Stewardship principles for the exercise of administrative and voting rights in listed companies.', 'Italy', 'governance', 'in_force', '2013-01-01'::date, 'Italy', 'https://www.carrotsandsticks.org/policies/85_22', ARRAY['guidance_frameworks', 'other sustainability policy', 'italy', 'sdg16', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('dd26d6f8-ce78-50e8-924e-473cd8d694d7', 'Italy Charter of Sustainable and Responsible Investment of Italian', 'Charter of Sustainable and Responsible Investment of Italian Finance', 'The Responsible Investment Charter sets out the Bank''s vision of sustainability and includes the principles and the reference criteria underlying the sustainable management of its financial investments; it also outlines the precise commitments through which it intends to make its work on a sustainable model for economic growth more concrete. The Charter applies to those financial assets managed under the Bank''s own responsibility, namely its financial portfolio and foreign exchange reserves investments. It does not apply to monetary policy portfolios, however, as they are managed by the Eurosystem. The principles and criteria set out in the Charter will guide the integration of sustainability assessments with financial ones; furthermore, the Bank seeks to use the Charter to foster greater awareness of these issues in the financial community with the goal of stimulating firms to adopt forms of management that are mindful of the environment, society and the best corporate governance practices.', 'The Responsible Investment Charter sets out the Bank''s vision of sustainability and includes the principles and the reference criteria underlying the sustainable management of its financial investments; it also outlines the precise commitments through which it intends to make its work on a sustainable model for economic growth more concrete. The Charter applies to those financial assets managed under the Bank''s own responsibility, namely its financial portfolio and foreign exchange reserves investments. It does not apply to monetary policy portfolios, however, as they are managed by the Eurosystem. The principles and criteria set out in the Charter will guide the integration of sustainability assessments with financial ones; furthermore, the Bank seeks to use the Charter to foster greater awareness of these issues in the financial community with the goal of stimulating firms to adopt forms of management that are mindful of the environment, society and the best corporate governance practices.', 'The Responsible Investment Charter sets out the Bank''s vision of sustainability and includes the principles and the reference criteria underlying the sustainable management of its financial investments; it also outlines the precise commitments through which it intends to make its work on a sustainable model for economic growth more concrete. The Charter applies to those financial assets managed under the Bank''s own responsibility, namely its financial portfolio and foreign exchange reserves investments. It does not apply to monetary policy portfolios, however, as they are managed by the Eurosystem. The principles and criteria set out in the Charter will guide the integration of sustainability assessments with financial ones; furthermore, the Bank seeks to use the Charter to foster greater awareness of these issues in the financial community with the goal of stimulating firms to adopt forms of management that are mindful of the environment, society and the best corporate governance practices.', 'Italy', 'climate', 'in_force', '2012-01-01'::date, 'Italy', 'https://www.carrotsandsticks.org/policies/85_27', ARRAY['italy', 'sdg11', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('aacdcee5-117d-5ec1-a46a-96f02bd29ac7', 'Italy Provisions on the investment policy implementation process', 'Provisions on the investment policy implementation process', 'The ''Provisions on the investment policy implementation process'' policy from Italy in 2012 aims to regulate the investment strategies of supplementary pension funds to ensure efficient risk-return combinations aligning with members'' social security needs. The policy requires pension schemes to define sub-funds, analyze demographic characteristics, review the investment policy every three years, and disclose contractual details with external parties. It emphasizes transparency, compliance, and periodic reporting to supervisory bodies and COVIP. The policy is mandatory and focuses on enhancing investment governance and outcomes in the pension sector.', 'The ''Provisions on the investment policy implementation process'' policy from Italy in 2012 aims to regulate the investment strategies of supplementary pension funds to ensure efficient risk-return combinations aligning with members'' social security needs. The policy requires pension schemes to define sub-funds, analyze demographic characteristics, review the investment policy every three years, and disclose contractual details with external parties. It emphasizes transparency, compliance, and periodic reporting to supervisory bodies and COVIP. The policy is mandatory and focuses on enhancing investment governance and outcomes in the pension sector.', 'The ''Provisions on the investment policy implementation process'' policy from Italy in 2012 aims to regulate the investment strategies of supplementary pension funds to ensure efficient risk-return combinations aligning with members'' social security needs. The policy requires pension schemes to define sub-funds, analyze demographic characteristics, review the investment policy every three years, and disclose contractual details with external parties. It emphasizes transparency, compliance, and periodic reporting to supervisory bodies and COVIP. The policy is mandatory and focuses on enhancing investment governance and outcomes in the pension sector.', 'Italy', 'climate', 'in_force', '2012-01-01'::date, 'Italy', 'https://www.carrotsandsticks.org/policies/85_28', ARRAY['other sustainability policy', 'italy', 'mandatory', 'sdg16', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('54e39435-66ed-55d4-9e09-07617fcd6f73', 'Italy Corporate Governance Code', 'Corporate Governance Code 2011', 'The Italian Corporate Governance Code 2011 is a voluntary policy aimed at enhancing corporate governance practices in listed Italian companies. It provides principles and criteria for effective board functioning, risk management, performance evaluation, and transparency. Companies adopting the code must report on the implementation of its recommendations in their Corporate Governance Reports. The code is monitored by the Corporate Governance Committee and has been updated over time to align with regulatory developments.', 'The Italian Corporate Governance Code 2011 is a voluntary policy aimed at enhancing corporate governance practices in listed Italian companies. It provides principles and criteria for effective board functioning, risk management, performance evaluation, and transparency. Companies adopting the code must report on the implementation of its recommendations in their Corporate Governance Reports. The code is monitored by the Corporate Governance Committee and has been updated over time to align with regulatory developments.', 'The Italian Corporate Governance Code 2011 is a voluntary policy aimed at enhancing corporate governance practices in listed Italian companies. It provides principles and criteria for effective board functioning, risk management, performance evaluation, and transparency. Companies adopting the code must report on the implementation of its recommendations in their Corporate Governance Reports. The code is monitored by the Corporate Governance Committee and has been updated over time to align with regulatory developments.', 'Italy', 'climate', 'in_force', '2011-01-01'::date, 'Italy', 'https://www.carrotsandsticks.org/policies/85_13', ARRAY['italy', 'regul