INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('87c315b8-6edc-57fe-9f14-7a72becde384', 'Italy Report on Operations Art. 2428 Civil Code', 'The Report on Operations Art. 2428 Civil Code', 'With this decree, the national legislator implemented the mandatory content of Directive 51/2003 / EC, known as the "accounting modernization directive", affecting on the preparation of the consolidated financial statements, management report and report by auditing of the companies concerned.', 'With this decree, the national legislator implemented the mandatory content of Directive 51/2003 / EC, known as the "accounting modernization directive", affecting on the preparation of the consolidated financial statements, management report and report by auditing of the companies concerned.', 'With this decree, the national legislator implemented the mandatory content of Directive 51/2003 / EC, known as the "accounting modernization directive", affecting on the preparation of the consolidated financial statements, management report and report by auditing of the companies concerned.', 'Italy', 'climate', 'in_force', '2009-01-01'::date, 'Italy', 'https://www.carrotsandsticks.org/policies/85_1', ARRAY['italy', 'mandatory', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
