INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f4c4133f-0c92-5a7d-95c4-2078274a335b', 'Italy Supervisory Provisions concerning Banks'' Organization and Corporate Governance', 'Supervisory Provisions concerning Banks'' Organization and Corporate Governance', 'A supervisory regulation regarding banks'' internal organization and corporate governance issued by the Bank of Italy.', 'A supervisory regulation regarding banks'' internal organization and corporate governance issued by the Bank of Italy.', 'A supervisory regulation regarding banks'' internal organization and corporate governance issued by the Bank of Italy.', 'Italy', 'governance', 'in_force', '2008-01-01'::date, 'Italy', 'https://www.carrotsandsticks.org/policies/85_23', ARRAY['italy', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ab4b43dc-5563-532d-82c9-26d9614f403b', 'Italy Legislative Decree 9 April 2008, n. 81. Implementation', 'Legislative Decree 9 April 2008, n. 81. Implementation of article 1 of the law of 3 August 2007, n. 123, concerning the protection of health and safety in the workplace', 'In 2008, the Italian government issued "Decreto Legislativo 9 aprile 2008, n. 81," which is a legislative decree that implements Article 1 of Law No. 123 of August 3, 2007, relating to the protection of health and safety in the workplace. The decree establishes guidelines and requirements for ensuring the safety and health of workers in all types of workplaces, including those in the public and private sectors. It outlines the responsibilities of employers, employees, and other stakeholders in ensuring workplace safety, and establishes procedures for risk assessment, accident prevention, and emergency preparedness. The decree also establishes penalties for violations of workplace safety regulations, and sets out procedures for reporting and investigating workplace accidents.', 'In 2008, the Italian government issued "Decreto Legislativo 9 aprile 2008, n. 81," which is a legislative decree that implements Article 1 of Law No. 123 of August 3, 2007, relating to the protection of health and safety in the workplace. The decree establishes guidelines and requirements for ensuring the safety and health of workers in all types of workplaces, including those in the public and private sectors. It outlines the responsibilities of employers, employees, and other stakeholders in ensuring workplace safety, and establishes procedures for risk assessment, accident prevention, and emergency preparedness. The decree also establishes penalties for violations of workplace safety regulations, and sets out procedures for reporting and investigating workplace accidents.', 'In 2008, the Italian government issued "Decreto Legislativo 9 aprile 2008, n. 81," which is a legislative decree that implements Article 1 of Law No. 123 of August 3, 2007, relating to the protection of health and safety in the workplace. The decree establishes guidelines and requirements for ensuring the safety and health of workers in all types of workplaces, including those in the public and private sectors. It outlines the responsibilities of employers, employees, and other stakeholders in ensuring workplace safety, and establishes procedures for risk assessment, accident prevention, and emergency preparedness. The decree also establishes penalties for violations of workplace safety regulations, and sets out procedures for reporting and investigating workplace accidents.', 'Italy', 'climate', 'in_force', '2008-01-01'::date, 'Italy', 'https://www.carrotsandsticks.org/policies/85_47', ARRAY['sdg8', 'italy', 'regulations', 'mandatory', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f9c53cf4-7640-53bd-9ed6-0d9c6a83a161', 'Italy Social Report Social Reporting of the Intangibles', 'The Social Report Social Reporting of the Intangibles', 'The ''Social Report Social Reporting of the Intangibles'' policy from Italy in 2008 provides guidance on social reporting of intangibles. It explores issues related to social reporting systems, intangible assets in accounting, and the strategic-social vision of companies. The document delves into identifying and synthesizing intangibles, addressing the social dimension of companies, and the relationship between stakeholders and intangibles. It aims to deepen understanding of intangibles and their impact on social reporting practices.', 'The ''Social Report Social Reporting of the Intangibles'' policy from Italy in 2008 provides guidance on social reporting of intangibles. It explores issues related to social reporting systems, intangible assets in accounting, and the strategic-social vision of companies. The document delves into identifying and synthesizing intangibles, addressing the social dimension of companies, and the relationship between stakeholders and intangibles. It aims to deepen understanding of intangibles and their impact on social reporting practices.', 'The ''Social Report Social Reporting of the Intangibles'' policy from Italy in 2008 provides guidance on social reporting of intangibles. It explores issues related to social reporting systems, intangible assets in accounting, and the strategic-social vision of companies. The document delves into identifying and synthesizing intangibles, addressing the social dimension of companies, and the relationship between stakeholders and intangibles. It aims to deepen understanding of intangibles and their impact on social reporting practices.', 'Italy', 'climate', 'in_force', '2008-01-01'