INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f308068f-5fdf-5c3f-ad32-3ddd9fecbc8b', 'Italy Implementation of EU Directive / EC amending Directives', 'Implementation of EU Directive 2003/51 / EC amending Directives 78/660, 83/349, 86/635 and 91/674 / EEC relating to the annual accounts and consolidated accounts of certain types of companies, banks and other financial institutions and insurance companies', 'This legislative decree is concerned with the Implementation of Directive 2003/51 / EC amending Directives 78/660, 83/349, 86/635 and 91/674 / EEC relating to the annual accounts and consolidated accounts of certain types of companies, banks and other financial institutions and insurance companies.', 'This legislative decree is concerned with the Implementation of Directive 2003/51 / EC amending Directives 78/660, 83/349, 86/635 and 91/674 / EEC relating to the annual accounts and consolidated accounts of certain types of companies, banks and other financial institutions and insurance companies.', 'This legislative decree is concerned with the Implementation of Directive 2003/51 / EC amending Directives 78/660, 83/349, 86/635 and 91/674 / EEC relating to the annual accounts and consolidated accounts of certain types of companies, banks and other financial institutions and insurance companies.', 'Italy', 'governance', 'in_force', '2007-01-01'::date, 'Italy', 'https://www.carrotsandsticks.org/policies/85_6', ARRAY['italy', 'mandatory', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1b3fe3af-1b12-50e5-9610-6b85c60462e3', 'Italy Corporate Governance Code (March Edition)', 'Corporate Governance Code (March Edition) 2006', 'The 2006 Italian Corporate Governance Code aims to enhance governance practices for listed companies by clarifying roles, improving transparency, and aligning with best practices. It emphasizes the importance of responsibilities towards investors, stakeholders, and good governance for value creation and shareholder protection. The code promotes the ''comply or explain'' principle and flexibility in implementation to accommodate company size, shareholding, and economic sector differences. It is designed to increase market understanding of each company''s governance model and foster interest and confidence among national and international investors and intermediaries.', 'The 2006 Italian Corporate Governance Code aims to enhance governance practices for listed companies by clarifying roles, improving transparency, and aligning with best practices. It emphasizes the importance of responsibilities towards investors, stakeholders, and good governance for value creation and shareholder protection. The code promotes the ''comply or explain'' principle and flexibility in implementation to accommodate company size, shareholding, and economic sector differences. It is designed to increase market understanding of each company''s governance model and foster interest and confidence among national and international investors and intermediaries.', 'The 2006 Italian Corporate Governance Code aims to enhance governance practices for listed companies by clarifying roles, improving transparency, and aligning with best practices. It emphasizes the importance of responsibilities towards investors, stakeholders, and good governance for value creation and shareholder protection. The code promotes the ''comply or explain'' principle and flexibility in implementation to accommodate company size, shareholding, and economic sector differences. It is designed to increase market understanding of each company''s governance model and foster interest and confidence among national and international investors and intermediaries.', 'Italy', 'climate', 'in_force', '2006-01-01'::date, 'Italy', 'https://www.carrotsandsticks.org/policies/85_14', ARRAY['italy', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a82aeaa4-d3c4-5b6c-b016-2accb84a394f', 'Italy Social Report Social Responsibility and Corporate Governance', 'The Social Report Social Responsibility and Corporate Governance', 'The report details the context of corporate governance in Italy and makes recommendations for how corporate governance can be advanced.', 'The report details the context of corporate governance in Italy and makes recommendations for how corporate governance can be advanced.', 'The report details the context of corporate governance in Italy and makes recommendations for how corporate governance can be advanced.', 'Italy', 'climate', 'in_force', '2006-01-01'::date, 'Italy', 'https://www.carrotsandsticks.org/policies/85_31', ARRAY['other sustainability policy', 'italy', 'mandatory', 'sdg16', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('50507146-7e9c-53a1-9ae2-aff53a6e793f', 'Italy Social Report Reporting Ambientale and Added Value', 'The Social Report Reporting Ambientale and Added Value', 'The research paper, ''Environmental Reporting and added value'', is the result of a common feeling of the GBS - and of the specially constituted research group - in on the need to deepen the issues of environmental survey and reporting.', 'The research paper, ''Environmental Reporting and added value'', is the result of a common feeling of the GBS - and of the specially constituted research group - in on the need to deepen the issues of environmental survey and reporting.', 'The research paper, ''Environmental Reporting and added value'', is the result of a common feeling of the GBS - and of the specially constituted research group - in on the need to deepen the issues of environmental survey and reporting.', 'Italy', 'climate', 'in_force', '2006-01-01'::date, 'Italy', 'https://www.carrotsandsticks.org/policies/85_36', ARRAY['sdg14', 'other sustainability policy', 'italy', 'mandatory', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a7912e36-ab5f-5eac-81e6-b0f396097cb0', 'Italy Legislative Decree 3 April 2006, n. 152. Environmental', 'Legislative Decree 3 April 2006, n. 152. Environmental regulations', 'This legislative decree has as its primary objective the promotion of the quality levels of human life, to be achieved through the safeguarding and improvement of the conditions of the environment and the wise and rational use of natural resources.', 'This legislative decree has as its primary objective the promotion of the quality levels of human life, to be achieved through the safeguarding and improvement of the conditions of the environment and the wise and rational use of natural resources.', 'This legislative decree has as its primary objective the promotion of the quality levels of human life, to be achieved through the safeguarding and improvement of the conditions of the environment and the wise and rational use of natural resources.', 'Italy', 'climate', 'in_force', '2006-01-01'::date, 'Italy', 'https://www.carrotsandsticks.org/policies/85_41', ARRAY['other sustainability policy', 'italy', 'sdg7', 'regulations', 'mandatory', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('22f14cc8-3e41-51b9-8c3d-55fd11491f0c', 'Italy Social Report The Performance Indicators In Social Reporting', 'The Social Report The Performance Indicators In Social Reporting', 'In 2006, Italy introduced the "Bilancio Sociale" or Social Balance, which is a tool for measuring the social and environmental performance of organizations. This tool is based on a set of performance indicators that are used in social reporting. The performance indicators include measures related to the organization''s social impact, such as employee welfare, community engagement, and environmental sustainability. The aim of the Bilancio Sociale is to encourage organizations to adopt a more comprehensive and responsible approach to their operations, and to be accountable to stakeholders for their social and environmental impact. By adopting the Bilancio Sociale, organizations can demonstrate their commitment to sustainable development and contribute to a more sustainable society.', 'In 2006, Italy introduced the "Bilancio Sociale" or Social Balance, which is a tool for measuring the social and environmental performance of organizations. This tool is based on a set of performance indicators that are used in social reporting. The performance indicators include measures related to the organization''s social impact, such as employee welfare, community engagement, and environmental sustainability. The aim of the Bilancio Sociale is to encourage organizations to adopt a more comprehensive and responsible approach to their operations, and to be accountable to stakeholders for their social and environmental impact. By adopting the Bilancio Sociale, organizations can demonstrate their commitment to sustainable development and contribute to a more sustainable society.', 'In 2006, Italy introduced the "Bilancio Sociale" or Social Balance, which is a tool for measuring the social and environmental performance of organizations. This tool is based on a set of performance indicators that are used in social reporting. The performance indicators include measures related to the organization''s social impact, such as employee welfare, community engagement, and environmental sustainability. The aim of the Bilancio Sociale is to encourage organizations to adopt a more comprehensive and responsible approach to their operations, and to be accountable to stakeholders for their social and environmental impact. By adopting the Bilancio Sociale, organizations can demonstrate their commitment to sustainable development and contribute to a more sustainable society.', 'Italy', 'climate', 'in_force', '2006-01-01'::date, 'Italy', 'https://www.carrotsandsticks.org/policies/85_49', ARRAY['italy', 'sdg11', 'mandatory', 'mandatory_regulations', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
