INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('206bb646-784e-5f0d-a27b-887c088b7da8', 'Italy Corporate Governance Code (Revised edition July', 'Corporate Governance Code (Revised edition July 2002)', 'The 2002 Italian Corporate Governance Code aims to guide listed companies in structuring effective boards of directors to set and achieve strategic objectives, supervise company performance, approve significant transactions, and ensure value creation for shareholders. It emphasizes directors'' autonomy, knowledge, and commitment to maximizing shareholder value. The policy recommends establishing guidelines for important transactions, appointing executive committees without diminishing the board''s responsibilities, and collecting directors'' position data annually. This disclosure-type policy targets companies listed on regulated markets in Italy, promoting transparency and accountability.', 'The 2002 Italian Corporate Governance Code aims to guide listed companies in structuring effective boards of directors to set and achieve strategic objectives, supervise company performance, approve significant transactions, and ensure value creation for shareholders. It emphasizes directors'' autonomy, knowledge, and commitment to maximizing shareholder value. The policy recommends establishing guidelines for important transactions, appointing executive committees without diminishing the board''s responsibilities, and collecting directors'' position data annually. This disclosure-type policy targets companies listed on regulated markets in Italy, promoting transparency and accountability.', 'The 2002 Italian Corporate Governance Code aims to guide listed companies in structuring effective boards of directors to set and achieve strategic objectives, supervise company performance, approve significant transactions, and ensure value creation for shareholders. It emphasizes directors'' autonomy, knowledge, and commitment to maximizing shareholder value. The policy recommends establishing guidelines for important transactions, appointing executive committees without diminishing the board''s responsibilities, and collecting directors'' position data annually. This disclosure-type policy targets companies listed on regulated markets in Italy, promoting transparency and accountability.', 'Italy', 'climate', 'in_force', '2002-01-01'::date, 'Italy', 'https://www.carrotsandsticks.org/policies/85_16', ARRAY['italy', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
